    substr(md5(seed_value), 13, 4) || '-' || substr(md5(seed_value), 17, 4) || '-' ||
    substr(md5(seed_value), 21, 12)
  )::uuid;
$function$;

CREATE OR REPLACE FUNCTION pg_temp.text_array(input_json JSONB)
RETURNS TEXT[] LANGUAGE SQL IMMUTABLE AS $function$
