          "label": "That read can be revised by new information",
          "order": 4
        },
        {
          "id": "mindset",
          "label": "Belief about stress changes experience, not physiology",
          "order": 5
        },
        {
          "id": "mismatch",
          "label": "Modern stressors mismatch a system built for short, physical threats",
          "order": 6
        }
      ],
      "transfer": {
        "prompt": "A learner says: 'my heart racing before this call proves something is wrong with me, and there's nothing I can do about how I read this situation.' What does this whole unit say back?",
